using System.Globalization;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using TerraRuntime.Contracts.Gameplay;
using TerraRuntime.Core;
using TerraRuntime.World;

namespace TerraRuntime.Tests;

public sealed class DungeonSurfaceBuildings1458Tests
{
    // Independent original Linux TerrariaServer1.4.5.8 SHA:
    // 4B87890AC53D40F61DB5F928693A379ACF4CCBD8ED3B47EB32FB096F145DF034.
    // Actual GenerateEntrance, six decorated/intersecting terrain fixtures, both sides, three palettes/seeds.
    // Actual crawler/style and potential-bounds bootstrap enables ordinary entrance stairs; cracked solidity is false.
    // All normalized16-byte cells, shared RNG and ordered feature metadata; no game source/assets embedded.
    public static IEnumerable<object[]> Buildings() => Reference.Split('\n', StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries).Select(row => new object[] { row });

    [Theory]
    [MemberData(nameof(Buildings))]
    public void Production_renderer_matches_original_whole_building(string reference)
    {
        string[] f = reference.Split('|');
        var kind = Enum.Parse<DungeonEntranceKind1458>(f[0]);
        int fixture = Int(f[1]), palette = Int(f[2]), seed = Int(f[3]);
        bool right = bool.Parse(f[4]);
        ushort brick = palette == 0 ? (ushort)41 : palette == 1 ? (ushort)43 : (ushort)44;
        var tiles = Fixture(fixture, (ushort)(7 + palette));
        var random = new RandomAdapter(6789);
        var renderer = new DungeonGraphGenerator1458.Renderer(tiles, brick, (ushort)(481 + palette), (ushort)(7 + palette),
            150.25, 220, 400, 1, 998, 25, 20, 35, 10, TestContext.Current.CancellationToken);
        var origin = new DungeonPoint1458(right ? 750 : 250, 180);
        var result = renderer.RenderEntrance(origin, kind, seed, random, !right);
        DungeonSamplingBoundsReference1458.AssertMatches($"{kind}|{fixture}|{palette}|{seed}|{right}", tiles.Dimensions,
            new(500, 450), [result.Component], result.GenerationTopOverride);
        Assert.Equal(f[5], Hash(tiles));
        Assert.Equal(Int(f[6]), random.Next());
        Assert.Equal(Point(f[7]), result.OldManSpawn);
        int[] b = f[8].Split(',').Select(Int).ToArray();
        Assert.Equal(new DungeonBounds1458(b[0], b[1], b[2] - 1, b[3] - 1), result.Component.Bounds);
        Assert.Equal(origin, result.Component.Start);
        Assert.Equal(result.OldManSpawn, result.Component.End);
        Assert.Null(result.Platform);
        Assert.Equal(f[9].Split(';').Select(Point), result.BuildingPlatforms.Select(p => p.Position));
        for (int i = 0; i < result.BuildingPlatforms.Count; i++)
        {
            var p = result.BuildingPlatforms[i];
            Assert.Equal(0, p.HeightFluff);
            Assert.True(p.ForcePlacement);
            Assert.Equal((double).33f, p.PotsChance);
            Assert.Equal(i < 3 ? 0 : .75, p.BooksChance);
            Assert.Equal(i < 3 ? 0 : (double).1f, p.PotionsChance);
            Assert.Equal(i >= 3 && (kind == DungeonEntranceKind1458.Tower || i < 5), p.NoWaterbolt);
        }
    }

    [Theory]
    [InlineData(false, 0)]
    [InlineData(false, 1)]
    [InlineData(false, 2)]
    [InlineData(true, 0)]
    [InlineData(true, 1)]
    [InlineData(true, 2)]
    public void Invalid_or_cancelled_building_rejects_before_mutation(bool tower, int failure)
    {
        var tiles = Fixture(0, 7);
        string before = Hash(tiles);
        var random = new RandomAdapter(6789);
        var builder = new DungeonSurfaceBuildings1458(tiles, 41, 481, failure == 1 ? (ushort)8 : (ushort)7, 150.25, random, new CancellationToken(failure == 0));
        var point = new DungeonPoint1458(failure == 2 ? 1 : 250, 180);
        if (failure == 0) Assert.Throws<OperationCanceledException>(() => Generate());
        else Assert.Throws<InvalidOperationException>(() => Generate());
        Assert.Equal(before, Hash(tiles));
        Assert.Equal(new RandomAdapter(6789).Next(), random.Next());
        void Generate() { if (tower) builder.GenerateTower(point, 42, true); else builder.GenerateDome(point, 42, true); }
    }

    internal static WorldTileStore Fixture(int f, ushort wall)
    {
        var tiles = new WorldTileStore(new WorldDimensions(1000, 600));
        for (int x = 0; x < 1000; x++)
        for (int y = 0; y < 600; y++)
        {
            bool active = y >= 145;
            ushort type = 1, background = 40;
            if (f == 2) { active = (x + y) % 3 == 0; background = (ushort)((x + y) % 4 == 0 ? wall : (x + y) % 4 == 1 ? 8 : 40); type = (ushort)((x + y) % 2 == 0 ? 41 : 481); }
            if (f == 0) { background = 0; active = false; }
            if (f == 5 && ((x >= 245 && x <= 255) || (x >= 745 && x <= 755))) { background = wall; active = false; }
            tiles.Set(x, y, new WorldTile
            {
                Type = type, Wall = background, FrameX = 18, FrameY = 36, TileColor = 3, WallColor = 4, LiquidAmount = 100,
                LiquidKind = (WorldLiquidKind)((x + y) % 4), Shape = (byte)((x + y) % 6),
                Flags = (active ? WorldTileFlags.Active : 0) | WorldTileFlags.WireRed | WorldTileFlags.InvisibleWall |
                    WorldTileFlags.FullbrightBlock | (f == 4 ? WorldTileFlags.Inactive : 0)
            });
        }
        return tiles;
    }
    internal static string Hash(WorldTileStore tiles)
    {
        int width = tiles.Dimensions.WidthTiles, height = tiles.Dimensions.HeightTiles;
        var ordered = new WorldTile[width * height];
        for (int x = 0; x < width; x++)
        for (int y = 0; y < height; y++) ordered[x * height + y] = tiles.Get(x, y);
        return Convert.ToHexString(SHA256.HashData(MemoryMarshal.AsBytes(ordered.AsSpan())));
    }
    internal static int Int(string value) => int.Parse(value, CultureInfo.InvariantCulture);
    private static DungeonPoint1458 Point(string text) { var p = text.Split(','); return new(Int(p[0]), Int(p[1])); }
    internal sealed class RandomAdapter(int seed) : IWorldGenerationVanillaRandom
    {
        private readonly VanillaUnifiedRandom1458 random = new(seed);
        public int Next() => random.Next();
        public int Next(int max) => random.Next(max);
        public int Next(int min, int max) => random.Next(min, max);
        public double NextDouble() => random.NextDouble();
        public void NextBytes(byte[] bytes) => random.NextBytes(bytes);
    }
